public void CL_AGUClashes(Side CurrentSide)
{
	try
	{
		if (!AGU_CONFIG.Instance.Enabled)
		{
			return;
		}
		foreach (ActiveUnit thisSideUnit in _ThisSideUnits)
		{
			if (thisSideUnit.IsAggregatedUnit)
			{
				((AggregateGroundUnit)thisSideUnit).HostileFrictionProportion.Clear();
			}
		}
	}
	catch (Exception projectError)
	{
		ProjectData.SetProjectError(projectError);
		ProjectData.ClearProjectError();
	}
}

