using Command_Core;
using Worldwind.Component;

private void CL_DrawMissionAreas()
{
	if (CommandLayer.IsAlaCarteDisabled("CL_DrawMissionAreas"))
	{
		return;
	}
	switch (SimConfiguration.DefaultGamePreferences.ShowMissionArea)
	{
	case Game.GamePreferences.ObjectVisibilitySetting.All:
		if (Client.CurrentSide == null)
		{
			break;
		}
		{
			foreach (Mission item in Client.CurrentSide.get_MissionsTotal(Client.CurrentScenario))
			{
				CL_DrawMissionArea(item);
			}
			break;
		}
	case Game.GamePreferences.ObjectVisibilitySetting.Selected:
		if (Client.MissionEditorWindow != null && Client.CurrentSide != null && Client.MissionEditorWindow.SelectedMission != null)
		{
			CL_DrawMissionArea(Client.MissionEditorWindow.SelectedMission);
		}
		break;
	case Game.GamePreferences.ObjectVisibilitySetting.DontShow:
		break;
	}
}

