private void method_62()
{
	try
	{
		if (Client.MapVisibleUnits == null || Client.MapVisibleUnits.Count == 0)
		{
			return;
		}
		list_60.Clear();
		list_60.AddRange(Client.MapVisibleUnits);
		list_60.Sort([SpecialName] (Module_Unit.Unit u1, Module_Unit.Unit u2) => u1.get_CurrentAltitude(DoSanityCheck: false, (GlobalVariables.BooleanObject)null).CompareTo(u2.get_CurrentAltitude(DoSanityCheck: false, (GlobalVariables.BooleanObject)null)));
		_UnitsJammed.Clear();
		Parallel.ForEach(list_60, [SpecialName] (Module_Unit.Unit theU) =>
		{
			if (theU.IsActiveUnit && ((ActiveUnit)theU).Sensory.JammerUnitsAreAffectingMe)
			{
				_UnitsJammed.TryAdd(theU.ObjectID, theU.ObjectID);
			}
		});
		method_61();
		foreach (Module_Unit.Unit item in list_60)
		{
			if (item.IsActiveUnit)
			{
				CL_DrawActiveUnit((ActiveUnit)item);
			}
			else if (GameGeneral.Beta_PlatformComms & Client.CurrentScenario.DeclaredFeatures.Contains(Scenario.ScenarioFeatureOption.PointToPointComm))
			{
				if (Client.SelectedUnit == null)
				{
					if (Operators.CompareString(Client.CurrentSide.HQ_ID, string.Empty, true) == 0)
					{
						CL_DrawContact((Contact)item);
						continue;
					}
					ActiveUnit activeUnit = Client.CurrentSide.Units.Where([SpecialName] (ActiveUnit HQ) => Operators.CompareString(HQ.ObjectID, Client.CurrentSide.HQ_ID, true) == 0).FirstOrDefault();
					if (activeUnit != null)
					{
						method_63(activeUnit);
					}
				}
				else if (Client.SelectedUnit.IsActiveUnit && Operators.CompareString(Client.SelectedUnit.get_UnitSide(SetSideOnly: false).ObjectID, Client.CurrentSide.ObjectID, true) == 0)
				{
					method_63((ActiveUnit)Client.SelectedUnit);
				}
				else
				{
					CL_DrawContact((Contact)item);
				}
			}
			else
			{
				CL_DrawContact((Contact)item);
