private void CL_DrawUncertaintyArea(Color theColor, ref Contact theContact)
{
	if (CommandLayer.IsAlaCarteDisabled("CL_DrawUncertaintyArea") || (theContact.IsFilteredOut && (Client.MouseHoveredUnit == null || theContact != Client.MouseHoveredUnit) && (Client.SelectedUnit == null || theContact != Client.SelectedUnit)))
	{
		return;
	}
	int line_thickness = ((theContact != Client.SelectedUnit) ? 1 : 3);
	if (theContact.UncertaintyArea != null)
	{
		if (theContact.Age > 0f)
		{
			theColor = Color.FromArgb(127, theColor.R, theColor.G, theColor.B);
		}
		commandLayer_0.DrawGeoLine(theColor, line_thickness, theContact.UncertaintyArea, closed: true);
	}
}

