public void GroupUnits()
{
	if (Client.CurrentSide == null || Client.CurrentSide.SelectedUnits.Count < 2)
	{
		return;
	}
	List<ActiveUnit> list = new List<ActiveUnit>();
	foreach (ActiveUnit item in Client.CurrentSide.SelectedUnits.Where([SpecialName] (Module_Unit.Unit theU) => !theU.IsContact()).ToList())
	{
		if (item.get_UnitSide(SetSideOnly: false) == null || item.get_UnitSide(SetSideOnly: false) != Client.CurrentSide)
		{
			continue;
		}
		try
		{
			ActiveUnit activeUnit2 = item;
			if (!item.IsGroupLead())
			{
				if (!activeUnit2.IsGroupMember() && (item.IsPlatform || item.IsGroup || item.IsAggregatedUnit))
				{
					list.Add(activeUnit2);
					activeUnit2.Doctrine.ClearCachedParentDoctrine();
					activeUnit2.Sensory.vmethod_2(activeUnit2.Sensors_Cached);
				}
			}
			else
			{
				list.Add(item.get_ParentGroup(UsingMissionPlanner: false));
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ex2?.Data.Add("Error at 200125", ex2.Message);
			GameGeneral.WriteExceptionsToLog(ex2);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}
	Client.DispatchSimpleUnitActionMultipleUnits(list, Client.SimpleUnitAction.Group);
}

