				string_10 = LandCover.GetUILabelText_LandCover(LandCover.GetLandCoverAndHeightAtThisPoint(thePoint.Latitude, thePoint.Longitude, Client.CurrentScenario, Client.CurrentScenario.GetNatureSide()).theTerrainType);
				if (string_10.Contains("Water"))
				{
					string_10 = string.Empty;
				}
				else
				{
					string_8 = string.Empty;
				}
			}
			return;
		}
		string_9 = "Slope: " + Conversions.ToString((int)Math.Round(100f * Terrain.GetMaxSlope(thePoint.Latitude, thePoint.Longitude, RequestIsFromGUI: true, Client.CurrentScenario))) + "% ";
		if (!Client.CurrentScenario.DeclaredFeatures.Contains(Scenario.ScenarioFeatureOption.LandTypeEffects))
		{
			string_10 = LandCover.GetUILabelText_LandCover(LandCover.GetLandCoverAtThisPoint(thePoint.Latitude, thePoint.Longitude, Client.CurrentScenario));
		}
		else
		{
			Side natureSide = Client.CurrentScenario.GetNatureSide();
			(LandCover.LandCoverType, int) landCoverAndHeightAtThisPoint = LandCover.GetLandCoverAndHeightAtThisPoint(thePoint.Latitude, thePoint.Longitude, Client.CurrentScenario, natureSide);
			string_10 = LandCover.GetUILabelText_LandCover(landCoverAndHeightAtThisPoint.Item1);
			if (landCoverAndHeightAtThisPoint.Item2 > 1)
			{
				if (!SimConfiguration.DefaultGamePreferences.ShowAltitudeInFeet)
				{
					string_10 = string_10 + "(Height: " + landCoverAndHeightAtThisPoint.Item2 + "m, Skyline: ";
					string_10 = string_10 + (landCoverAndHeightAtThisPoint.Item2 + elevation) + "m)";
				}
				else
				{
					int num3 = (int)Math.Round((float)elevation * 3.28084f);
					int num4 = (int)Math.Round((float)landCoverAndHeightAtThisPoint.Item2 * 3.28084f);
					string_10 = string_10 + "(Height: " + num4 + "ft, Skyline: ";
					string_10 = string_10 + (num4 + num3) + "ft)";
				}
			}
		}
		string_8 = string.Empty;
	}
	else
	{
		string_7 = "";
	}
}

using System;
using System.Diagnostics;
using System.Drawing;
