using Microsoft.VisualBasic.CompilerServices;

private void method_206()
{
	try
	{
		if (WorldWindow1 != null)
		{
			WorldWindow worldWindow = WorldWindow1;
			ref Point currentMousePosition = ref CurrentMousePosition;
			int PointX = currentMousePosition.X;
			ref Point currentMousePosition2 = ref CurrentMousePosition;
			int PointY = currentMousePosition2.Y;
			double WorldLon = default(double);
			double WorldLat = default(double);
			WWC.WWC_ScreenToWorld(worldWindow, ref PointX, ref PointY, ref WorldLon, ref WorldLat);
			currentMousePosition2.Y = PointY;
			currentMousePosition.X = PointX;
			if (double.IsNaN(WorldLon) || double.IsNaN(WorldLat))
			{
				return;
			}
			DateTime time = Client.CurrentScenario.Time;
			bool use_DST = Client.CurrentScenario.Use_DST;
			string dST_Start = Client.CurrentScenario.DST_Start;
			string dST_End = Client.CurrentScenario.DST_End;
			string text = Misc.LocalTime(time, WorldLon, use_DST, dST_Start, dST_End).ToString("HH:mm:ss");
			Weather.TTimeOfDayType timeOfDay = SunModule.GetTimeOfDay(Client.CurrentScenario, time.Year, time.Month, time.Day, time.Hour, time.Minute, time.Second, UseCurrentScenarioTime: true, WorldLat, WorldLon, 0.0);
			string text2 = "(" + SunModule.GetTimeOfDay_String(timeOfDay, time, WorldLon, use_DST, dST_Start, dST_End) + ")";
			switch (timeOfDay)
			{
			case Weather.TTimeOfDayType.tod_Day:
				text2 = "(Day)";
				break;
			case Weather.TTimeOfDayType.tod_Twilight:
				text2 = ((Misc.LocalTime(time, WorldLon, use_DST, dST_Start, dST_End).Hour >= 12) ? "(Dusk)" : "(Dawn)");
				break;
			case Weather.TTimeOfDayType.tod_Night:
				text2 = "(Night)";
				break;
			}
			string text3 = "Weather: ";
			Weather.WeatherProfile weatherProfile = Weather.get_WeatherAtThisTimeAndPlace(Client.CurrentScenario, WorldLat, WorldLon, 0);
			text3 = text3 + Conversions.ToString((int)weatherProfile.get_ActualTempAtSL(timeOfDay)) + "°C - " + weatherProfile.CloudInfo_Description + " - " + weatherProfile.RainfallRate_Description + " - Wind/Sea " + Conversions.ToString(weatherProfile.SeaState);
			string text4 = "";
			if (Client.SelectedUnit != null)
			{
				float num = Math2.CalcDist(Client.SelectedUnit.get_Latitude((GlobalVariables.BooleanObject)null), Client.SelectedUnit.get_Longitude((GlobalVariables.BooleanObject)null), WorldLat, WorldLon);
				text4 = ((num < 1f) ? (" - " + Conversions.ToString((int)Math.Round(num * 1852f)) + "m from sel") : ((!(num < 10f)) ? (" - " + $"{num:0}" + "nm from sel") : (" - " + $"{num:0.00}" + "nm from sel")));
			}
			switch (SimConfiguration.DefaultGamePreferences.MapCursorBox)
			{
			case Game.GamePreferences.MapCursorBoxVisibilitySetting.AtCursor:
			case Game.GamePreferences.MapCursorBoxVisibilitySetting.Bottom:
				DataCursorMouseX = CurrentMousePosition.X;
				DataCursorMouseY = CurrentMousePosition.Y;
				DataCursorLine1 = Misc.CoordinateToString(WorldLat, WorldLon, SimConfiguration.DefaultGamePreferences.GeoCoordinateType) + text4 + string_7 + " ";
				if (!string.IsNullOrEmpty(string_8))
				{
					DataCursorLine2 = string_8 + " ";
				}
				else
				{
					DataCursorLine2 = string_9 + " - " + string_10 + " ";
				}
				DataCursorLine3 = "Local time: " + text + " " + text2 + " ";
				DataCursorLine4 = text3 + " ";
				break;
			}
		}
		else
		{
			GameGeneral.WriteLogDebugInfoToFile("WorldWindow1 object not found! Error 200596");
		}
	}
	catch (Exception ex)
	{
		ProjectData.SetProjectError(ex);
		Exception ex2 = ex;
		ex2?.Data.Add("Error at 200601", ex2.Message);
		GameGeneral.WriteExceptionsToLog(ex2);
		if (Debugger.IsAttached)
		{
			Debugger.Break();
		}
		ProjectData.ClearProjectError();
	}
}

