			{
				Client.CurrentGame.Pause();
			}
			Game._GameMode gameMode = Client.CurrentGame.GameMode;
			if (gameMode != Game._GameMode.MonteCarlo)
			{
				Client.theFloatingLicenseErrorForm.ScenarioToSave = Client.CurrentScenario;
			}
			Client.theFloatingLicenseErrorForm.ErrorReason = Client.FloatingLicenseErrorMessage;
			((Control)Client.theFloatingLicenseErrorForm).Show();
			return;
		}
		Queue<LoggedMessage> unhandledPopUpMessages = Client.CurrentScenario.UnhandledPopUpMessages;
		if (unhandledPopUpMessages != null && unhandledPopUpMessages.Count > 0)
		{
			method_208();
		}
		if (Client.MustRefreshMainForm || Client.CurrentGame.Status == Game._GameStatus.Running)
		{
			method_157();
			Client.MustRefreshMainForm = false;
		}
		method_78();
		method_28();
	}
	catch (Exception ex)
	{
		ProjectData.SetProjectError(ex);
		Exception ex2 = ex;
		ex2?.Data.Add("Error at 200201", ex2.Message);
		GameGeneral.WriteExceptionsToLog(ex2);
		if (Debugger.IsAttached)
		{
			Debugger.Break();
		}
		ProjectData.ClearProjectError();
	}
}

using System.Windows.Forms;
using Command_Core;

private void method_208()
{
	while (Client.CurrentScenario.UnhandledPopUpMessages.Count > 0)
	{
		LoggedMessage loggedMessage = Client.CurrentScenario.UnhandledPopUpMessages.Dequeue();
		if (Client.CurrentSide != null && (loggedMessage.Side == Client.CurrentSide || loggedMessage.Side == null))
		{
			NewMessageForm value = null;
			Client.OpenMessageWindows.TryGetValue(loggedMessage.Type, out value);
			if (value == null)
			{
				value = new NewMessageForm();
				Client.OpenMessageWindows.Add(loggedMessage.Type, value);
			}
			value.Messages.Add(loggedMessage);
		}
	}
	int num;
	if (Client.CurrentGame.Status == Game._GameStatus.Running)
	{
		if (Realtime)
		{
			num = 0;
		}
		else if (Client.OpenMessageWindows.Values.Count <= 0)
		{
			num = 0;
		}
		else
		{
			Client.CurrentGame.Pause();
			num = 0;
		}
	}
	else
	{
		num = 0;
	}
	bool flag = (byte)num != 0;
	foreach (NewMessageForm value2 in Client.OpenMessageWindows.Values)
	{
		((Control)value2).Show();
		flag = true;
	}
	if (flag && Client.CurrentGame.Status == Game._GameStatus.Paused)
	{
		RightColumn1.RefreshPanels(Client.CurrentScenario, Client.CurrentSide, Client.SelectedUnit, v: false);
	}
}

