public void HandleMapProfileSettingsChange()
{
	if ((WorldWindow1 == null) | (Main.Instance == null))
	{
		return;
	}
	MapProfile currentMapProfile = Client.CurrentMapProfile;
	if (currentMapProfile == null)
	{
		return;
	}
	if (!Client.AllowGodModeActions)
	{
		currentMapProfile.GodsEye = false;
	}
	((ToolStripMenuItem)AirSensorsToolStripMenuItem).Checked = currentMapProfile.RangeSymbol_AASensor != MapProfile._ShowElement.DontShow;
	((ToolStripMenuItem)AirWeaponsToolStripMenuItem).Checked = currentMapProfile.RangeSymbol_AAWeapon != MapProfile._ShowElement.DontShow;
	((ToolStripMenuItem)SurfaceSensorsToolStripMenuItem).Checked = currentMapProfile.RangeSymbol_ASSensor != MapProfile._ShowElement.DontShow;
	((ToolStripMenuItem)SurfaceWeaponsToolStripMenuItem).Checked = currentMapProfile.RangeSymbol_ASWeapon != MapProfile._ShowElement.DontShow;
	((ToolStripMenuItem)LandWeaponsToolStripMenuItem).Checked = currentMapProfile.RangeSymbol_AGWeapon != MapProfile._ShowElement.DontShow;
	((ToolStripMenuItem)UnderwaterSensorsToolStripMenuItem).Checked = currentMapProfile.RangeSymbol_ASWSensor != MapProfile._ShowElement.DontShow;
	((ToolStripMenuItem)UnderwaterWeaponsToolStripMenuItem).Checked = currentMapProfile.RangeSymbol_ASWWeapon != MapProfile._ShowElement.DontShow;
	TSMI_AircraftRange.Checked = currentMapProfile.RangeSymbol_ACRange != MapProfile._ShowElement.DontShow;
	((ToolStripMenuItem)MergeRangesymbolsToolStripMenuItem).Checked = currentMapProfile.MergeRangeSymbols;
	((ToolStripMenuItem)ShowNonfriendlyToolStripMenuItem).Checked = currentMapProfile.ShowNonFriendly;
	((ToolStripMenuItem)VirtualEarthTSMI).Checked = currentMapProfile.Layer_VirtualEarth;
	((ToolStripMenuItem)MapLatLonGridToolStripMenuItem).Checked = currentMapProfile.ShowLatLonGrid;
	((ToolStripMenuItem)TSMI_BaseEarthLayer).Checked = currentMapProfile.ShowBaseEarth;
	((ToolStripMenuItem)BMNGLayerToolStripMenuItem).Checked = currentMapProfile.Layer_BMNG;
	TSMI_Sentinel2.Checked = currentMapProfile.Layer_Sentinel2;
	((ToolStripMenuItem)ReliefLayerToolStripMenuItem).Checked = currentMapProfile.Layer_Relief;
	((ToolStripMenuItem)TSMI_StamenTerrain).Checked = currentMapProfile.Layer_StamenTerrain;
	((ToolStripMenuItem)TSMI_StamenRoads).Checked = currentMapProfile.Layer_StamenRoads;
	((ToolStripMenuItem)BordersCoastlinesToolStripMenuItem).Checked = currentMapProfile.Layer_Borders;
	((ToolStripMenuItem)PlacenamesToolStripMenuItem).Checked = currentMapProfile.Layer_Placenames;
	TSMI_LandCover.Checked = currentMapProfile.Layer_LandCover;
	TSMI_OpenTopoMap.Checked = currentMapProfile.Layer_OpenTopoMap;
	TSMI_OSMVector.Checked = currentMapProfile.Layer_OSMVector;
	((ToolStripMenuItem)DayNightLightingToolStripMenuItem).Checked = currentMapProfile.DayNightLighting;
	if (Realtime)
	{
		((ToolStripMenuItem)TSMI2).Enabled = false;
		if (currentMapProfile.ShowIlluminationVectors == MapProfile._ShowElement.All)
		{
			currentMapProfile.ShowIlluminationVectors = MapProfile._ShowElement.SelectedUnit;
		}
		((ToolStripMenuItem)TSMI5).Enabled = false;
		if (currentMapProfile.ShowTargetingVectors == MapProfile._ShowElement.All)
		{
			currentMapProfile.ShowTargetingVectors = MapProfile._ShowElement.SelectedUnit;
		}
		((ToolStripMenuItem)TSMI11).Enabled = false;
		if (currentMapProfile.ShowDatalinks == MapProfile._ShowElement.All)
		{
			currentMapProfile.ShowDatalinks = MapProfile._ShowElement.SelectedUnit;
		}
		((ToolStripMenuItem)TSMI8).Enabled = false;
		if (currentMapProfile.ShowDatablocks == MapProfile._ShowElement.All)
		{
			currentMapProfile.ShowDatablocks = MapProfile._ShowElement.SelectedUnit;
		}
		((ToolStripMenuItem)TSMI41).Enabled = false;
		if (SimConfiguration.DefaultGamePreferences.ShowFlightPlans_Airborne == Game.GamePreferences.FlightPlansVisibilitySetting_Airborne.All)
		{
			SimConfiguration.DefaultGamePreferences.ShowFlightPlans_Airborne = Game.GamePreferences.FlightPlansVisibilitySetting_Airborne.SelectedUnit;
		}
		((ToolStripMenuItem)TSMI_CON1).Enabled = false;
		if (SimConfiguration.DefaultGamePreferences.ShowContrails == Game.GamePreferences.ContrailsVisibilitySetting.All)
		{
			SimConfiguration.DefaultGamePreferences.ShowContrails = Game.GamePreferences.ContrailsVisibilitySetting.SelectedUnit;
		}
		((ToolStripMenuItem)TSMI_WC1).Enabled = false;
		if (SimConfiguration.DefaultGamePreferences.ShowWakeCavitation == Game.GamePreferences.WakeCavitationVisibilitySetting.All)
		{
			SimConfiguration.DefaultGamePreferences.ShowWakeCavitation = Game.GamePreferences.WakeCavitationVisibilitySetting.SelectedUnit;
		}
	}
	switch (currentMapProfile.ShowDatalinks)
	{
	case MapProfile._ShowElement.All:
		((ToolStripMenuItem)TSMI10).Checked = false;
		((ToolStripMenuItem)TSMI11).Checked = true;
		((ToolStripMenuItem)TSMI12).Checked = false;
		break;
	case MapProfile._ShowElement.SelectedUnit:
		((ToolStripMenuItem)TSMI10).Checked = true;
		((ToolStripMenuItem)TSMI11).Checked = false;
		((ToolStripMenuItem)TSMI12).Checked = false;
		break;
	case MapProfile._ShowElement.DontShow:
		((ToolStripMenuItem)TSMI10).Checked = false;
		((ToolStripMenuItem)TSMI11).Checked = false;
		((ToolStripMenuItem)TSMI12).Checked = true;
		break;
	}
	switch (currentMapProfile.ShowDatablocks)
	{
	case MapProfile._ShowElement.All:
		((ToolStripMenuItem)TSMI7).Checked = false;
		((ToolStripMenuItem)TSMI8).Checked = true;
		((ToolStripMenuItem)TSMI9).Checked = false;
