		((ToolStripMenuItem)TSMI13).Checked = false;
		((ToolStripMenuItem)TSMI14).Checked = false;
		((ToolStripMenuItem)TSMI15).Checked = true;
		break;
	}
	switch (currentMapProfile.ShowContactEmissions_Details)
	{
	case MapProfile._ShowEmissionTypes.All:
		((ToolStripMenuItem)AllEmissionsToolStripMenuItem).Checked = true;
		((ToolStripMenuItem)FireControlOnlyToolStripMenuItem).Checked = false;
		((ToolStripMenuItem)AllEmissionsForSelectedContactFireControlOnlyForRestToolStripMenuItem).Checked = false;
