public void ShowDoctrineROE(ScenarioObject theScenObject, ref ReadOnlyCollection<Module_Unit.Unit> theSelectedUnits, ref List<ActiveUnit> theSelectedActiveUnit, bool UnitIsOperating)
{
	DoctrineForm doctrineForm = new DoctrineForm();
	doctrineForm.UnitIsOperating = UnitIsOperating;
	doctrineForm.RefreshSelectedUnits(theScenObject, ref theSelectedUnits, ref theSelectedActiveUnit);
	if (Information.IsNothing((object)doctrineForm.Subject) && (Information.IsNothing((object)doctrineForm.SelectedUnits) || doctrineForm.SelectedUnits.Count == 0) && !Information.IsNothing((object)theScenObject) && (object)theScenObject.GetType() != typeof(Side))
	{
		return;
	}
	if (!Information.IsNothing((object)doctrineForm.Subject))
	{
		if ((object)doctrineForm.Subject.GetType() == typeof(Group))
		{
			Group obj = (Group)doctrineForm.Subject;
			if (!Information.IsNothing((object)obj.GroupLead))
			{
				doctrineForm.isEscorts = obj.GroupLead.AI.IsEscort;
			}
			else
			{
				doctrineForm.isEscorts = false;
			}
		}
		else if ((object)doctrineForm.Subject.GetType() == typeof(ActiveUnit))
		{
			doctrineForm.isEscorts = ((ActiveUnit)doctrineForm.Subject).AI.IsEscort;
		}
	}
	if (Information.IsNothing((object)doctrineForm.Subject))
	{
		doctrineForm.Subject = Client.CurrentSide;
	}
	((Control)doctrineForm).Show();
}

