	{
		if (Operators.CompareString(Client.SaveScenarioPath, (string)null, true) == 0)
		{
			((FileDialog)SaveScenarioDialog).InitialDirectory = GameGeneral.ScenariosRootPath;
			((FileDialog)SaveScenarioDialog).FileName = Module1.ConvertScenTitleToFileName(Client.CurrentScenario.Title);
		}
		else
		{
			((FileDialog)SaveScenarioDialog).InitialDirectory = Path.GetDirectoryName(Client.SaveScenarioPath);
			((FileDialog)SaveScenarioDialog).FileName = Client.SaveScenarioPath;
		}
		bool flag;
		if (flag = Client.CurrentGame.Status == Game._GameStatus.Running)
		{
			Client.CurrentGame.Pause();
		}
		((FileDialog)SaveScenarioDialog).AddExtension = true;
		if (Client.CurrentGame.GameMode == Game._GameMode.ScenEdit)
		{
			((FileDialog)SaveScenarioDialog).Filter = "Command scenario file (*.scen)|*.scen|Command saved game (*.save)|*.save|All Files (*.*)|*.*";
		}
		else
		{
			((FileDialog)SaveScenarioDialog).Filter = "Command saved game (*.save)|*.save|Command scenario file (*.scen)|*.scen|All Files (*.*)|*.*";
		}
		if (!string.IsNullOrEmpty(((FileDialog)SaveScenarioDialog).InitialDirectory))
		{
			if (!Path.GetFullPath(((FileDialog)SaveScenarioDialog).InitialDirectory).StartsWith(GameGeneral.ScenariosRootPath))
			{
				((FileDialog)SaveScenarioDialog).InitialDirectory = GameGeneral.ScenariosRootPath;
			}
		}
		else
		{
			((FileDialog)SaveScenarioDialog).InitialDirectory = GameGeneral.ScenariosRootPath;
		}
		DialogResult val = ((CommonDialog)SaveScenarioDialog).ShowDialog();
		int currentUserAction;
		switch (val - 1)
		{
		default:
			currentUserAction = 0;
			break;
		case 0:
			Client.SaveCurrentScenario(SBR: false);
			((Control)this).Enabled = true;
			Client.SaveScenarioPath = ((FileDialog)SaveScenarioDialog).FileName;
			Client.AddFileNameToRecentList(Client.SaveScenarioPath);
			currentUserAction = 0;
			break;
		case 1:
			((Control)this).Enabled = true;
			currentUserAction = 0;
			break;
		case 2:
			((Control)this).Enabled = true;
			currentUserAction = 0;
			break;
		case 3:
		case 4:
		case 5:
			currentUserAction = 0;
			break;
		case 6:
			((Control)this).Enabled = true;
			currentUserAction = 0;
			break;
		}
		Client.CurrentUserAction = (Client.UserAction)currentUserAction;
		if (!flag)
		{
			result = 1;
		}
		else
		{
			Client.CurrentGame.Run();
			result = 1;
		}
	}
	return (byte)result != 0;
}

