private void method_345(object sender, EventArgs e)
{
	if (Client.CurrentScenario.IsRunningInCampaignMode)
	{
		List<string> list = new List<string>();
		Campaign.GetCampaignsInFolder(GameGeneral.ScenariosRootPath, list);
		foreach (string item in list)
		{
			Campaign campaign = Campaign.ReadFromFile(item);
			if (Operators.CompareString(campaign.ID, Client.CurrentScenario.CampaignID, true) == 0)
			{
				Client.SaveScenarioPath = Path.Combine(Path.GetDirectoryName(item), Guid.NewGuid().ToString() + ".save");
				break;
			}
		}
	}
	if (Operators.CompareString(Client.SaveScenarioPath, (string)null, true) == 0)
	{
		method_170(RuntimeHelpers.GetObjectValue(sender), e);
		return;
	}
	bool num = Client.CurrentGame.Status == Game._GameStatus.Running;
	if (num)
	{
		Client.CurrentGame.Pause();
	}
	((Control)this).Enabled = false;
	Client.SaveCurrentScenario(SBR: false, Client.SaveScenarioPath);
	Client.AddFileNameToRecentList(Client.SaveScenarioPath);
	((Control)this).Enabled = true;
	Client.CurrentUserAction = Client.UserAction.None;
	if (num)
	{
		Client.CurrentGame.Run();
	}
}

