		Client.CurrentSide.NoNavZones.Add(noNavZone);
		MyProject.Forms.ReferencePointManager.ShowWithSelectedZone((IWin32Window)(object)this, noNavZone);
	}
	else
	{
		DarkMessageBox.ShowError("You must select at least three reference points in order to create a nav zone.", "Not enough reference points selected!");
	}
}

