using DarkUI.Forms;
using Microsoft.VisualBasic;

private void method_456(object sender, EventArgs e)
{
	//IL_0017: Unknown result type (might be due to invalid IL or missing references)
	//IL_0100: Unknown result type (might be due to invalid IL or missing references)
	//IL_0105: Unknown result type (might be due to invalid IL or missing references)
	//IL_0106: Unknown result type (might be due to invalid IL or missing references)
	//IL_0108: Unknown result type (might be due to invalid IL or missing references)
	//IL_012a: Expected I4, but got Unknown
	if (Information.IsNothing((object)Client.CurrentSide))
	{
		DarkMessageBox.ShowError("You must have at least one side created in order to package a scenario.", "No side exists!");
		return;
	}
	((FileDialog)SaveScenarioDialog).Title = "Package scenario for distribution";
	((Control)this).Enabled = false;
	if (!Information.IsNothing((object)Client.CurrentScenario.FileName))
	{
		((FileDialog)SaveScenarioDialog).InitialDirectory = GameGeneral.ScenariosRootPath;
		((FileDialog)SaveScenarioDialog).FileName = Module1.ConvertScenTitleToFileName(Client.CurrentScenario.FileName);
		bool flag;
		if (flag = Client.CurrentGame.Status == Game._GameStatus.Running)
		{
			Client.CurrentGame.Pause();
		}
		((FileDialog)SaveScenarioDialog).AddExtension = true;
		((FileDialog)SaveScenarioDialog).Filter = "Packaged scenario file (*.zip)|*.zip";
		if (string.IsNullOrEmpty(((FileDialog)SaveScenarioDialog).InitialDirectory))
		{
			((FileDialog)SaveScenarioDialog).InitialDirectory = GameGeneral.ScenariosRootPath;
		}
		else if (!Path.GetFullPath(((FileDialog)SaveScenarioDialog).InitialDirectory).StartsWith(GameGeneral.ScenariosRootPath))
		{
			((FileDialog)SaveScenarioDialog).InitialDirectory = GameGeneral.ScenariosRootPath;
		}
		DialogResult val = ((CommonDialog)SaveScenarioDialog).ShowDialog();
		int currentUserAction;
		switch (val - 1)
		{
		default:
			currentUserAction = 0;
			break;
		case 0:
			AttachmentRepoManager.PackageScenarioForDistribution(Client.CurrentScenario, Client.CurrentSide, ((FileDialog)SaveScenarioDialog).FileName);
			((Control)this).Enabled = true;
			Client.SaveScenarioPath = ((FileDialog)SaveScenarioDialog).FileName;
			currentUserAction = 0;
			break;
		case 1:
			((Control)this).Enabled = true;
			currentUserAction = 0;
			break;
		case 2:
			((Control)this).Enabled = true;
			currentUserAction = 0;
			break;
		case 3:
		case 4:
		case 5:
			currentUserAction = 0;
			break;
		case 6:
			((Control)this).Enabled = true;
			currentUserAction = 0;
			break;
		}
		Client.CurrentUserAction = (Client.UserAction)currentUserAction;
		if (flag)
		{
			Client.CurrentGame.Run();
		}
	}
	else
	{
		Client.CurrentUserAction = Client.UserAction.PackingScenarioForDistribution;
	}
}

