private void method_489(object sender, EventArgs e)
{
	if (!Client.SimulationThread.IsAlive)
	{
		if (Debugger.IsAttached)
		{
			Debugger.Break();
		}
		Client.SimulationThread = new Thread(Client.CoreSimulation_Main);
		Client.SimulationThread.Priority = ThreadPriority.Lowest;
		Client.SimulationThread.Start();
	}
	if (!Information.IsNothing((object)Client.CurrentScenario) && !Information.IsNothing((object)Client.CurrentSide) && Client.CurrentSide.SelectedUnits.Count <= 1 && Client.CurrentGame.Status == Game._GameStatus.Running && (RightColumn1.UpdateData || (!Information.IsNothing((object)Client.SelectedUnit) && (Client.SelectedUnit.IsWeapon || Client.SelectedUnit.IsContact()))))
	{
		RightColumn1.RefreshPanels(Client.CurrentScenario, Client.CurrentSide, Client.SelectedUnit, v: false, IsCyclicRefresh: true);
	}
}

