private void method_491(object sender, MouseEventArgs e)
{
	//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
	//IL_00b3: Invalid comparison between Unknown and I4
	if (Client.CurrentSide == null)
	{
		return;
	}
	if (Realtime)
	{
		Client.DispatchSimpleContactActionMultipleContacts(Client.CurrentSide.Contacts_List, Client.SimpleContactAction.FilterOutCivilianOn);
		FilteroutCivilianToolStripMenuItem.Checked = true;
		Client.MustRefreshMainForm = true;
		return;
	}
	foreach (Contact contacts_ in Client.CurrentSide.Contacts_List)
	{
		if (contacts_.SideIsKnown && (contacts_.get_Stance(Client.CurrentSide) == Misc.PostureStance.Neutral || FilteroutNeutralToolStripMenuItem.Checked || FilteroutFriendlyToolStripMenuItem.Checked) && contacts_.IsCivilian)
		{
			contacts_.IsFilteredOut = true;
		}
	}
	int mustRefreshMainForm;
	if ((int)e.Button == 2097152)
	{
		FilteroutCivilianToolStripMenuItem.Checked = true;
		mustRefreshMainForm = 1;
	}
	else
	{
		mustRefreshMainForm = 1;
	}
	Client.MustRefreshMainForm = (byte)mustRefreshMainForm != 0;
}

