using System;
using System.IO;
using System.Windows.Forms;
using Command_Core;
using Command_Core.LoadSave;
using DarkUI.Forms;

private void method_501(object sender, EventArgs e)
{
	//IL_000b: Unknown result type (might be due to invalid IL or missing references)
	//IL_0011: Invalid comparison between Unknown and I4
	//IL_006c: Unknown result type (might be due to invalid IL or missing references)
	//IL_0072: Invalid comparison between Unknown and I4
	//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
	if ((int)DarkMessageBox.ShowWarning("Are you sure? This will create a stripped-down copy of the current DB and bind the scenario to it!", "Confirm", DarkDialogButton.OkCancel) == 1)
	{
		if (string.IsNullOrEmpty(((FileDialog)SaveScenarioDialog).InitialDirectory))
		{
			((FileDialog)SaveScenarioDialog).InitialDirectory = GameGeneral.ScenariosRootPath;
		}
		else if (!Path.GetFullPath(((FileDialog)SaveScenarioDialog).InitialDirectory).StartsWith(GameGeneral.ScenariosRootPath))
		{
			((FileDialog)SaveScenarioDialog).InitialDirectory = GameGeneral.ScenariosRootPath;
		}
		if ((int)((CommonDialog)SaveScenarioDialog).ShowDialog() == 1)
		{
			string CustomDBFileName = default(string);
			DB_Misc.BindScenToCustomDB(Client.CurrentScenario, ref CustomDBFileName);
			LoadSave.SaveScenario(Client.CurrentScenario, Client.CurrentSide, ((FileDialog)SaveScenarioDialog).FileName, SBR: false);
			DarkMessageBox.ShowInformation("Done! Custom DB for this scenario is: " + CustomDBFileName, "");
		}
	}
}

