private void method_506(object sender, EventArgs e)
{
	//IL_0032: Unknown result type (might be due to invalid IL or missing references)
	//IL_0109: Unknown result type (might be due to invalid IL or missing references)
	if (Realtime || RealtimeAC)
	{
		foreach (ToolStripItem item in (ArrangedElementCollection)((ToolStripDropDownItem)FileToolStripMenuItem).DropDownItems)
		{
			item.Enabled = false;
		}
		((ToolStripItem)RealtimeToolStripMenuItem).Visible = true;
		RealtimeToolStripMenuItem.Enabled = true;
		RealtimeJoinToolStripMenuItem.Enabled = false;
		RealtimeDisconnectToolStripMenuItem.Enabled = true;
		((ToolStripMenuItem)ExitToolStripMenuItem).Enabled = true;
		if (Client.AllowEditModeActions)
		{
			((ToolStripMenuItem)TSMI_LoadScenario).Enabled = true;
			TSMI_LoadRecent.Enabled = true;
			((ToolStripMenuItem)TSMI_SaveScen).Enabled = true;
			((ToolStripMenuItem)TSMI_SaveAs).Enabled = true;
		}
		return;
	}
	if (!((ToolStripDropDownItem)FileToolStripMenuItem).DropDownItems[0].Enabled)
	{
		foreach (ToolStripItem item2 in (ArrangedElementCollection)((ToolStripDropDownItem)FileToolStripMenuItem).DropDownItems)
		{
			item2.Enabled = true;
		}
		RealtimeJoinToolStripMenuItem.Enabled = true;
		RealtimeDisconnectToolStripMenuItem.Enabled = false;
	}
	else
	{
		((ToolStripItem)RealtimeToolStripMenuItem).Visible = true;
		RealtimeToolStripMenuItem.Enabled = true;
		RealtimeJoinToolStripMenuItem.Enabled = true;
		RealtimeDisconnectToolStripMenuItem.Enabled = false;
		((ToolStripItem)RealtimeToolStripMenuItem).Visible = GameGeneral.Beta_CivRTMP;
		RealtimeToolStripMenuItem.Enabled = GameGeneral.Beta_CivRTMP;
		((ToolStripItem)RealtimeJoinToolStripMenuItem).Visible = GameGeneral.Beta_CivRTMP;
		RealtimeJoinToolStripMenuItem.Enabled = GameGeneral.Beta_CivRTMP;
		((ToolStripItem)RealtimeDisconnectToolStripMenuItem).Visible = GameGeneral.Beta_CivRTMP;
		RealtimeDisconnectToolStripMenuItem.Enabled = false;
	}
	if (!Client.CurrentScenario.IsRunningInCampaignMode)
	{
		((ToolStripMenuItem)TSMI_SaveAs).Enabled = true;
	}
	else
	{
		((ToolStripMenuItem)TSMI_SaveAs).Enabled = false;
	}
	if (Client.CurrentScenario.ExecutionInProgress)
	{
		((ToolStripMenuItem)TSMI_NewScenario).Enabled = false;
		((ToolStripMenuItem)TSMI_LoadScenario).Enabled = false;
		TSMI_LoadRecent.Enabled = false;
		((ToolStripItem)TSMI_NewScenario).ToolTipText = "Pause current scenario before starting new Scenario";
		((ToolStripItem)TSMI_LoadScenario).ToolTipText = "Pause current scenario before starting new Scenario";
		((ToolStripItem)TSMI_LoadRecent).ToolTipText = "Pause current scenario before starting new Scenario";
	}
	else
	{
		((ToolStripMenuItem)TSMI_NewScenario).Enabled = true;
		((ToolStripMenuItem)TSMI_LoadScenario).Enabled = true;
		TSMI_LoadRecent.Enabled = true;
		((ToolStripItem)TSMI_NewScenario).ToolTipText = "";
		((ToolStripItem)TSMI_LoadScenario).ToolTipText = "";
		((ToolStripItem)TSMI_LoadRecent).ToolTipText = "";
	}
	if (GameGeneral.PE_MPOnly)
	{
		((ToolStripMenuItem)TSMI_NewScenario).Enabled = false;
		((ToolStripMenuItem)TSMI_LoadScenario).Enabled = false;
		TSMI_LoadRecent.Enabled = false;
		((ToolStripMenuItem)TSMI_SaveScen).Enabled = false;
		((ToolStripMenuItem)TSMI_SaveAs).Enabled = false;
		TSMI_Benchmark.Enabled = false;
	}
	if (Realtime)
	{
		((ToolStripMenuItem)TSMI_NewScenario).Enabled = false;
	}
}

