private void method_515(object sender, EventArgs e)
{
	StringBuilder stringBuilder = new StringBuilder();
	bool flag = false;
	foreach (Module_Unit.Unit selectedUnit in Client.CurrentSide.SelectedUnits)
	{
		if (!Information.IsNothing((object)selectedUnit))
		{
			if (flag)
			{
				stringBuilder.Append(" , ");
			}
			stringBuilder.Append("{name='" + selectedUnit.Name.ToString() + "', guid='" + selectedUnit.ObjectID + "'}");
			flag = true;
		}
	}
	Clipboard.SetText(stringBuilder.ToString());
}

