using Command_Core;
using Microsoft.VisualBasic;

public void ToggleIsolatedPOV()
{
	if (!Client.CurrentScenario.DeclaredFeatures.Contains(Scenario.ScenarioFeatureOption.CommsDisruption))
	{
		return;
	}
	if (string.IsNullOrEmpty(Client.CurrentMapProfile.IsolatedPOVObjectID))
	{
		if (Information.IsNothing((object)Client.SelectedUnit) || !Client.SelectedUnit.IsActiveUnit)
		{
			return;
		}
		Client.CurrentMapProfile.IsolatedPOVObjectID = Client.SelectedUnit.ObjectID;
	}
	else
	{
		Client.CurrentMapProfile.IsolatedPOVObjectID = null;
	}
	MessageLogControlViewModel.ResetLog();
	Client.MustRefreshMainForm = true;
}

