private void method_625(object sender, EventArgs e)
{
	if (Client.CurrentSide == null || Client.CurrentSide.SelectedUnits.Count < 2)
	{
		return;
	}
	List<ActiveUnit> list = new List<ActiveUnit>();
	foreach (ActiveUnit item in Client.CurrentSide.SelectedUnits.Where([SpecialName] (Module_Unit.Unit theU) => !theU.IsContact()).ToList())
	{
		if (item.get_UnitSide(SetSideOnly: false) == null || item.get_UnitSide(SetSideOnly: false) != Client.CurrentSide)
		{
			continue;
		}
		try
		{
			if (item.IsFacility || item.IsMobileGroundUnit)
			{
				list.Add(item);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ex2?.Data.Add("Error at 20045125", ex2.Message);
			GameGeneral.WriteExceptionsToLog(ex2);
			if (Debugger.IsAttached)
			{
				Debugger.Break();
			}
			ProjectData.ClearProjectError();
		}
	}
	AggregateGroundUnit aggregateGroundUnit = new AggregateGroundUnit(Client.CurrentScenario);
	aggregateGroundUnit.Name = "New AGU";
	aggregateGroundUnit.Echelon = AggregateGroundUnit.GroundEchelonLevel.Squad;
	aggregateGroundUnit.MobileUnitCategory = IMobileGroundUnit._MobileUnitCategory.Infantry;
	foreach (ActiveUnit item2 in list.ToList())
	{
		if (!item2.IsAggregatedUnit)
		{
			aggregateGroundUnit.AddOrRemoveActualRoster(AggregateGroundUnit.GetAnnexAndDBID(item2.DBID, item2.UnitType), 1, AutomaticallyAlignAssignedRoster: true);
		}
		else
		{
			AggregateGroundUnit aggregateGroundUnit2 = (AggregateGroundUnit)item2;
			foreach (KeyValuePair<string, (ActiveUnit, int)> item3 in aggregateGroundUnit2.GetActualRoster_Readonly())
			{
				aggregateGroundUnit.AddOrRemoveActualRoster(item3.Key, item3.Value.Item2, AutomaticallyAlignAssignedRoster: true);
			}
		}
		item2.Destroy(ScenEditAction: true, IsFacilityAimpoint: false, DestroyUnitNow: true, "AGU integration", null, RegisterAsLosses: false);
	}
	Module_Unit.Unit unit = Client.CurrentSide.SelectedUnits.ElementAt(0);
	Client.CurrentScenario.AddAggregateUnit(aggregateGroundUnit, Client.CurrentSide, unit.get_Longitude((GlobalVariables.BooleanObject)null), unit.get_Latitude((GlobalVariables.BooleanObject)null));
}

